import heapq


class MedianFinder:
    def __init__(self) -> None:
        self.low: list[int] = []  # the smaller half, negated so the min heap acts as a max heap
        self.high: list[int] = []  # the bigger half, a min heap

    def add_num(self, num: int) -> None:
        heapq.heappush(self.low, -num)
        # Move the biggest of the smaller half up, so all of low stays at or below all of high.
        heapq.heappush(self.high, -heapq.heappop(self.low))
        # Keep low the same size as high, or one bigger.
        if len(self.high) > len(self.low):
            heapq.heappush(self.low, -heapq.heappop(self.high))

    def find_median(self) -> float:
        if len(self.low) > len(self.high):
            return -self.low[0]
        return (-self.low[0] + self.high[0]) / 2


n = int(input())
finder = MedianFinder()
for num in map(int, input().split()):
    finder.add_num(num)
    print(f"{finder.find_median():.1f}")

