import java.util.Collections;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        MedianFinder finder = new MedianFinder();
        for (int i = 0; i < n; i++) {
            finder.addNum(in.nextInt());
            System.out.printf("%.1f%n", finder.findMedian());
        }
    }
}

class MedianFinder {
    // The smaller half, its biggest on top.
    private final PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder());
    // The bigger half, its smallest on top.
    private final PriorityQueue<Integer> high = new PriorityQueue<>();

    void addNum(int num) {
        low.offer(num);
        // Move the biggest of the smaller half up, so all of low stays at or below all of high.
        high.offer(low.poll());
        // Keep low the same size as high, or one bigger.
        if (high.size() > low.size()) {
            low.offer(high.poll());
        }
    }

    double findMedian() {
        if (low.size() > high.size()) {
            return low.peek();
        }
        return (low.peek() + high.peek()) / 2.0;
    }
}

