package main

import (
	"container/heap"
	"fmt"
)

// minHeap implements heap.Interface with the smallest number on top.
type minHeap []int

func (h minHeap) Len() int            { return len(h) }
func (h minHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *minHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// maxHeap implements heap.Interface with the biggest number on top.
type maxHeap []int

func (h maxHeap) Len() int            { return len(h) }
func (h maxHeap) Less(i, j int) bool  { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *maxHeap) Pop() interface{} {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

// MedianFinder keeps the numbers seen so far.
type MedianFinder struct {
	low  maxHeap // the smaller half, its biggest on top
	high minHeap // the bigger half, its smallest on top
}

func (m *MedianFinder) addNum(num int) {
	heap.Push(&m.low, num)
	// Move the biggest of the smaller half up, so all of low stays at or below all of high.
	heap.Push(&m.high, heap.Pop(&m.low))
	// Keep low the same size as high, or one bigger.
	if m.high.Len() > m.low.Len() {
		heap.Push(&m.low, heap.Pop(&m.high))
	}
}

func (m *MedianFinder) findMedian() float64 {
	if m.low.Len() > m.high.Len() {
		return float64(m.low[0])
	}
	return float64(m.low[0]+m.high[0]) / 2
}

func main() {
	var n int
	fmt.Scan(&n)
	finder := MedianFinder{}
	for i := 0; i < n; i++ {
		var num int
		fmt.Scan(&num)
		finder.addNum(num)
		fmt.Printf("%.1f\n", finder.findMedian())
	}
}

