// A small binary heap, since TypeScript has none built in. You don't need to
// change it. compare(a, b) < 0 means a comes out first, so (a, b) => a - b
// makes a min heap and (a, b) => b - a a max heap.
class Heap<T> {
  private items: T[];
  private compare: (a: T, b: T) => number;

  // Starts empty, or builds the heap from a whole list at once.
  constructor(compare: (a: T, b: T) => number, items: T[] = []) {
    this.compare = compare;
    this.items = [...items];
    for (let i = Math.floor(this.items.length / 2) - 1; i >= 0; i--) {
      this.siftDown(i);
    }
  }

  size(): number {
    return this.items.length;
  }

  peek(): T | undefined {
    return this.items[0];
  }

  push(item: T): void {
    this.items.push(item);
    let i = this.items.length - 1;
    while (i > 0 && this.before(i, Math.floor((i - 1) / 2))) {
      this.swap(i, Math.floor((i - 1) / 2));
      i = Math.floor((i - 1) / 2);
    }
  }

  pop(): T | undefined {
    const top = this.items[0];
    const last = this.items.pop();
    if (last !== undefined && this.items.length > 0) {
      this.items[0] = last;
      this.siftDown(0);
    }
    return top;
  }

  private before(i: number, j: number): boolean {
    const a = this.items[i];
    const b = this.items[j];
    return a !== undefined && b !== undefined && this.compare(a, b) < 0;
  }

  private swap(i: number, j: number): void {
    const a = this.items[i];
    const b = this.items[j];
    if (a !== undefined && b !== undefined) {
      this.items[i] = b;
      this.items[j] = a;
    }
  }

  private siftDown(i: number): void {
    for (;;) {
      let best = i;
      for (const child of [2 * i + 1, 2 * i + 2]) {
        if (this.before(child, best)) {
          best = child;
        }
      }
      if (best === i) {
        return;
      }
      this.swap(i, best);
      i = best;
    }
  }
}

